-- Ascent ALM - Phase 4: data sources and the lobby. Hand-written; apply with
--   node scripts/apply-migration.cjs supabase/migrations/20261020000000_data_sources.sql
--
-- A data source is a named feed of one kind of data owned by one affiliate (or GROUP for market data):
-- uploads are made to a source, so a user never picks an affiliate on a data screen. Same table shape as
-- every other table: the app's record in `data jsonb`, filter columns generated from it.
--
-- Also: batches gain generated source_id / checksum columns (the source a load came through, and the file's
-- content hash used to refuse the same file twice); GROUP's market-data sources are created; every existing
-- affiliate gets its default manual-upload sources (positions per department, ledger, counterparties and
-- history). New affiliates get theirs from the app when they are created (src/lib/dataSources.ts).

-- ─── data_sources ───────────────────────────────────────────────────────────

create table if not exists public.data_sources (
  id text primary key,
  data jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  affiliate_code text generated always as ((data->>'affiliateCode')) stored,
  domain text generated always as ((data->>'domain')) stored,
  is_active boolean generated always as (coalesce((data->>'isActive')::boolean, true)) stored
);
create index if not exists data_sources_affiliate_code_idx on public.data_sources (affiliate_code);
create index if not exists data_sources_domain_idx on public.data_sources (domain);
create index if not exists data_sources_is_active_idx on public.data_sources (is_active);
do $$ begin
  alter table public.data_sources add constraint data_sources_id_matches_data check (data->>'id' = id);
exception when duplicate_object then null; end $$;
drop trigger if exists data_sources_touch on public.data_sources;
create trigger data_sources_touch before update on public.data_sources for each row execute function app.touch_updated_at();
alter table public.data_sources enable row level security;

drop policy if exists data_sources_read on public.data_sources;
drop policy if exists data_sources_insert on public.data_sources;
drop policy if exists data_sources_update on public.data_sources;
drop policy if exists data_sources_delete on public.data_sources;
create policy data_sources_read on public.data_sources for select to authenticated
  using (app.has_perm('dashboard.view') and app.affiliate_ok(affiliate_code));
create policy data_sources_insert on public.data_sources for insert to authenticated
  with check (app.affiliate_write_ok(affiliate_code) and app.has_any_perm(array['data.configure', 'group.manage', 'affiliate.manage']));
create policy data_sources_update on public.data_sources for update to authenticated
  using (app.affiliate_write_ok(affiliate_code) and app.has_any_perm(array['data.configure', 'group.manage', 'affiliate.manage']))
  with check (app.affiliate_write_ok(affiliate_code) and app.has_any_perm(array['data.configure', 'group.manage', 'affiliate.manage']));
create policy data_sources_delete on public.data_sources for delete to authenticated
  using (app.affiliate_write_ok(affiliate_code) and app.has_any_perm(array['data.configure', 'group.manage', 'affiliate.manage']));

grant select, insert, update, delete on public.data_sources to authenticated;
revoke all on public.data_sources from anon;

-- ─── batches: source and file checksum ──────────────────────────────────────

alter table public.batches add column if not exists source_id text generated always as ((data->>'sourceId')) stored;
alter table public.batches add column if not exists checksum text generated always as ((data->>'checksum')) stored;
create index if not exists batches_source_id_idx on public.batches (source_id);
create index if not exists batches_checksum_idx on public.batches (checksum);

